/**
 * Generated by `npm run db:types` after the migrations are pushed (Task 2–4).
 *
 * Until then this is a permissive stand-in: every table/view/function is
 * loosely typed so the client compiles. Regenerate once the DB is live to get
 * real column types, then delete this comment.
 */
 
type LooseTable = { Row: any; Insert: any; Update: any; Relationships: [] };
type LooseFn = { Args: Record<string, any>; Returns: any };

export type Database = {
  public: {
    Tables: { [table: string]: LooseTable };
    Views: { [view: string]: { Row: any } };
    Functions: { [fn: string]: LooseFn };
    Enums: { [name: string]: string };
    CompositeTypes: Record<string, never>;
  };
};
